import os
import json
from taf.ul.bts_components.core.device import Device
from ..pylogger.logger import log_input_and_output, log_result, log_env_state, log_operation, log_step
from .exceptions import WrongSoapUpdateStatus, UnknownCommandContent
from ..parser.rmod.fault_history_log import FaultHistory


class Rmod(Device):

    def __init__(self):
        super(Rmod, self).__init__()

    @log_input_and_output
    def connect_to(self, address, username='root', password='root', proxy=None, alias=None):
        """
        Connects to radio unit via ssh.

        :param address: Address to RU
        :type address: str
        :param username: radio username to log in
        :type username: str
        :param password: radio username password
        :type password: str
        :param proxy: proxy device through which connection will be open; defaults to None,
                      then no proxy device alias will be required to perform connection procedure to RU
        :type proxy: Str
        :param alias: Name of device; if None provided then default alias will be used
        :type alias: str or None
        """
        self._connect_to(
            hostname=address, username=username, password=password, proxy=proxy, alias=alias
        )

    @log_input_and_output
    def change_value_of_parameter_in_dir(self, parameter, new_value):
        """
        Changes value of parameter in DIR file.

        :param parameter: name of parameter that will be changed
        :type parameter: str
        :param new_value: new value to be set in DIR
        :type new_value: str
        """
        params = str(self._check_for_permission_denied_and_reexecute("cat /mnt/sw/DIR1"))

        for param in params.split(" "):
            if parameter in param.split("="):
                self._check_for_permission_denied_and_reexecute("cat /mnt/sw/DIR1 | sed s'/{}/{}/' > /mnt/sw/DIR".format(
                    "".join(param), param.replace(param, '{}="{}"'.format(parameter, new_value))))

        self._check_for_permission_denied_and_reexecute("cat /mnt/sw/DIR > /mnt/sw/DIR1")
        self._check_for_permission_denied_and_reexecute('rm /mnt/sw/DIR')

    @log_input_and_output
    def check_absent_dir1_backup(self):
        """
        Checks if there is no DIR1 backup.

        :return: True if there is DIR1_backup, False otherwise
        :rtype: bool
        """
        params = self.execute("ls /mnt/sw/")

        for param in params.split(" "):
            if 'DIR1_backup' in param:
                return True

        return False

    @log_input_and_output
    def check_status_update_param_in_soap(self):
        """
        Checks param update status in soap.

        :raises: WrongSoapUpdateStatus exception if param update status will differ from 'ok' in soap xml log
        """
        status = os.popen("sudo cat /tmp/UnitOAM_SOAP_Log.xml | grep ptpConfig | grep acceptedClockClasses "
                          "| grep -oP '(?<=<status>).*?(?=</status>)'").read()
        status = status.split('\n')
        log_env_state("Read status: {}".format(status))

        if status[-2].lower() != 'ok':
            raise WrongSoapUpdateStatus("Status update in soap: {}".format(status[-2]))

    @log_input_and_output
    def get_rfsw_from_ru(self):
        """
        Gets radio software from Radio's version file or issue file if version does not exist.

        :return: Radio Sw eg. 'FRM59.10.R16L', empty string if can't be obtained.
        :rtype str
        """
        rfsw_version = self._get_rfsw_from_ru_version_file()

        if rfsw_version != "":
            return rfsw_version

        else:
            return self._get_rfsw_from_ru_issue_file()

    @log_input_and_output
    def get_rfsw_from_ru_active_partition(self):
        """
        Gets radio software version using Radio's DIR1 file or slot_1 file (active partition).
        :rtype str
        """
        rfsw_version = self._get_rfsw_from_ru_dir_1_file()

        return rfsw_version if rfsw_version else self._get_rfsw_from_ru_slot_1_file()

    @log_input_and_output
    def check_ip_address_in_radio(self, ru_ip_subnet='192.168.254', interface='eth0'):
        """
        Checks ip address in ifconfig.

        :return: checks whether there is ru_ip_subnet in ifconfig
        :rtype bool
        """
        cmd = '/sbin/ifconfig {}'.format(interface) + \
              ' | grep -e "inet addr:[0-9.]*" | sed -e "s/[ ]*inet addr://" | cut -d ' ' -f 1'

        return ru_ip_subnet in str(self.execute(cmd))

    @log_input_and_output
    def get_soap_file_path(self):
        """
        Gets Unit OAM SOAP log xml path from radio.

        :return: Unit OAM SOAP log path if exists, None otherwise
        :rtype  str or None
        """
        default_file_path = '/ram/UnitOAM_SOAP_Log{}.xml{}'

        if self.file_exists(remote_path=default_file_path.format("", ".gz")):
            self.execute("gzip -d {}".format(default_file_path.format("", ".gz")))

        if self.file_exists(remote_path=default_file_path.format("", "")):
            return default_file_path.format("", "")

        if self.file_exists(remote_path=default_file_path.format("0", ".gz")):
            self.execute("gzip -d {}".format(default_file_path.format("0", ".gz")))

        if self.file_exists(remote_path=default_file_path.format("0", "")):
            return default_file_path.format("0", "")

    @log_input_and_output
    def get_product_name(self):
        """
        Gets radio product name using Radio's manifest file.
        :rtype str
        """
        manifest_file = str(self._check_for_permission_denied_and_reexecute("cat /run/coma/type/manifest"))
        log_env_state("Read manifest file: {}".format(manifest_file))

        if 'No such file or directory' in manifest_file:
            log_result('Manifest file does not exist, returning empty string.')
            return ""

        return manifest_file.split('.')[0]

    @log_input_and_output
    def get_fault_history(self):
        """
        Gets Fault History log parsed from fault_history_log.txt from Radio Unit.

        :return: Dictionary with information about active, inactive faults and faults events.
        :rtype:  dict
        """
        log_path = '/ram/fault_history_log.txt'

        log_operation("Getting fault history log...")
        raw_log = self.execute("cat {0}".format(log_path))

        log_step("Raw log has been read, parsing...")
        log_env_state(raw_log)

        parser = FaultHistory(log=raw_log)

        parsed_log = parser.parse()
        log_result("Faults History has been successfully parsed.")

        return parsed_log

    @log_input_and_output
    def set_swconfig_flag(self, flag, value):
        """
        Sets flag in swconfig.txt file on RU.

        :param flag: flag for which value will be assigned
        :type flag: str
        :param value: value for flag provided
        :type value: str
        :rtype: str
        """
        response = self._check_for_permission_denied_and_reexecute("ccsShell.sh rad -mpw {} {}".format(flag, value))
        return response

    def get_beamforming_calibration_details(self):
        """ Gets beamforming calibration information """
        response = self._check_for_permission_denied_and_reexecute("bfcali -stat")
        return response

    @log_input_and_output
    def _get_rfsw_from_ru_version_file(self):
        version_file = str(self._check_for_permission_denied_and_reexecute("cat /etc/version"))
        log_env_state("Read version file: {}".format(version_file))

        if 'No such file or directory' in version_file:
            log_result('Version file does not exist, returning empty string.')
            return ""

        version = version_file.split()

        try:
            return version[0]

        except IndexError:
            raise UnknownCommandContent('Content of /etc/version has changed and parser need to aligned!')

    @log_input_and_output
    def _get_rfsw_from_ru_issue_file(self):
        issue_file = str(self._check_for_permission_denied_and_reexecute("cat /etc/issue"))

        if 'No such file or directory' in issue_file:
            log_result('Issue file does not exist, returning empty string.')
            return ""

        version = issue_file.split()

        try:
            return version[-5]

        except IndexError:
            raise UnknownCommandContent('Content of /etc/version has changed and parser needs to be aligned!')

    @log_input_and_output
    def _get_rfsw_from_ru_dir_1_file(self):
        dir1_file = str(self._check_for_permission_denied_and_reexecute("cat /mnt/sw/DIR1"))

        if 'No such file or directory' in dir1_file:
            log_result('DIR1 file does not exist, returning empty string')
            return ""

        try:
            version = dir1_file.split()[1].split('=')[1].strip('"')
            return version

        except IndexError:
            raise UnknownCommandContent('Content of /mnt/sw/DIR1 has changed and parser needs to be aligned!')

    @log_input_and_output
    def _get_rfsw_from_ru_slot_1_file(self):
        slot_1_file = str(self._check_for_permission_denied_and_reexecute("cat /mnt/runtime/swman/slot_1"))

        if 'No such file or directory' in slot_1_file:
            log_result('slot_1 file does not exist, returning empty string')
            return ""

        content = json.loads(slot_1_file)

        try:
            version = content["value0"]["value2"]
            return version

        except KeyError:
            raise UnknownCommandContent('Content of /mnt/runtime/swman/slot_1 '
                                        'has changed and parser needs to be aligned!')

    @log_input_and_output
    def _check_for_permission_denied_and_reexecute(self, cmd):
        returned_value = self.execute(cmd)
        if "permission denied" in str(returned_value).lower():
            return self.execute("sudo {}".format(cmd))
        return returned_value
